mapper.select:
SELECT sa.*, j.title AS job_title, e.company_name, w.name AS worker_name, w.phone AS worker_phone FROM schedule_applications sa LEFT JOIN jobs j ON sa.job_id = j.id LEFT JOIN enterprises e ON j.company_id = e.id LEFT JOIN workers w ON sa.worker_id = w.id
AND sa.status = #{status}
AND j.company_id = #{companyId}
AND (j.title LIKE CONCAT('%', #{keyword}, '%') OR w.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sa.applied_at DESC
